import os
import os.path
import shutil
import sys

from robot.api.deco import keyword
from robot.libraries.BuiltIn import BuiltIn


arg = ''
opt = ''
atOutputDir = ''
atOutputName = ''
analysisDef = ''
analysisDefName = ''
fileInputDesc = ''

okForRun = True


def SetAnalyseName(aName):
    global analysisDefName

    analysisDef = aName
    defList = analysisDef.split('/')
    analysisDefName = defList[-1]


def AT(analysisDefinition, traceInput, dictionaryVariable=None):
    global arg, atOutputName, atOutputDir, okForRun

    okForRun = True
    result = -1
    arg = ""
    atOutputName = ""
    atOutputDir = ""
    SetAnalyseName(analysisDefinition)

    if TestFileExist(analysisDefinition):

        GetOptionLine(analysisDefinition, traceInput, dictionaryVariable)

        okForRun = okForRun and (len(arg) > 0)

        if (okForRun):
            localDir = os.path.dirname(os.path.abspath(__file__)) + '/bin'
            os.environ["LD_LIBRARY_PATH"] = localDir

            command = localDir + '/AnalysisTraces -a ' + analysisDefinition + " " + arg + ' 2>./stderr.txt'
            LogMsg('argument: ' + arg)

            result = os.WEXITSTATUS(os.system(command))

            if ((result != 0) and (result != 1) and (result != 2)):
                result = -1
                # else:
                #    LogMsgError('AnalysisTraces not run, Bad Input')
                #    okForRun = False

    return result


# Return Analyse file result: 0 OK, 1 NOK, 2 N/A, -1 Analysis fail
#   analysisDefinition: analysis definition
#   traceInput:         file to analysed
#   ictionaryVariable: variable to initialyze (Key = variable name or 'options'): ex. DUnumber=32  options=-g

@keyword('eCLAT-AnalysisTraces')
def eAT_AnalysisTracesWithResult(analysisDefinition, traceInput, dictionaryVariable=None):
    return AnalysisTracesWithResult(analysisDefinition, traceInput, dictionaryVariable)


@keyword('AnalysisTraces')
def AnalysisTracesWithResult(analysisDefinition, traceInput, dictionaryVariable=None):
    result = AT(analysisDefinition, traceInput, dictionaryVariable)

    if (result != 0):
        if (okForRun):
            LogWarning(result)
        else:
            LogError(result)
    else:
        LogInfo(result)

    return result


# True if Analyse file is OK
#  analysisDefinition: analysis definition
#  traceInput:         file to analised
#  dictionaryVariable: variable to initialyse (Key = variable name or 'options'): ex. DUnumber=32  options=-g
@keyword('eCLAT-AnalysisTraces Is Passed')
def eAT_AnalysisTracesIsPassed(analysisDefinition, traceInput, dictionaryVariable=None):
    return AnalysisTracesIsPassed(analysisDefinition, traceInput, dictionaryVariable)


@keyword('AnalysisTraces Is Passed')
def AnalysisTracesIsPassed(analysisDefinition, traceInput, dictionaryVariable=None):
    # SetAnalyseName(analysisDefinition)

    result = AT(analysisDefinition, traceInput, dictionaryVariable)

    if (result != 0):
        LogError(result)
        BuiltIn().fail()
    else:
        LogInfo(result)

    return result


def LogResultMsg(result):
    if result == 0:
        msgErr = 'AnalysisTraces (' + analysisDefName + '): PASS'
    else:
        if (okForRun):
            errorTxt = open('./stderr.txt', 'r').read()
            msgErr = 'AnalysisTraces (' + analysisDefName + '): ' + errorTxt
        else:
            msgErr = 'AnalysisTraces (' + analysisDefName + '): Not run'

    return msgErr


def LogInfo(result):
    BuiltIn().log(LogResultMsg(result), html=True, console=True, repr=True)


def LogWarning(result):
    BuiltIn().log(LogResultMsg(result), level='WARN', html=True, console=True, repr=True)


def LogError(result):
    BuiltIn().log(LogResultMsg(result), level='ERROR', html=True, console=True, repr=True)


def LogMsg(msgError):
    BuiltIn().log('AnalysisTraces (' + analysisDefName + '): ' + msgError, html=True, console=True, repr=True)


def LogMsgWarning(msgError):
    BuiltIn().log('AnalysisTraces (' + analysisDefName + '): ' + msgError, level='WARN', html=True, console=True,
                  repr=True)


def LogMsgError(msgError):
    BuiltIn().log('AnalysisTraces (' + analysisDefName + '): ' + msgError, level='ERROR', html=True, console=True,
                  repr=True)


# Create string with all option used
# if files input correspond to a list, an intermediate json file is created
def GetOptionLine(analysisDefinition, traceInput, dictionaryVariable=None):
    global opt

    opt = ''

    if (isinstance(dictionaryVariable, dict)):
        for key, value in dictionaryVariable.items():
            if key != 'options':
                opt += '-v ' + key + ' ' + str(value) + ' '
            else:
                opt += value + ' '

    forceOutputName = ReadOutputFileNameInOption(opt)

    CreateArgInputTraceFile(traceInput, forceOutputName)


def ReadOutputFileNameInOption(options):
    if ('-o' in options):
        optlist = options.split(' ')
        n = optlist.index('-o')
        output = optlist[n + 1]

        LogMsg('with -o ' + output)
    else:
        output = ''

    return output


def CreateArgInputTraceFile(traceInput, forceOutputName=None):
    if (isinstance(traceInput, list)):
        CreateArgInputTraceFileByList(traceInput, forceOutputName)
    else:
        if (isinstance(traceInput, dict)):
            CreateArgInputTraceFileByDico(traceInput, forceOutputName)
        else:
            CreateArgInputTraceFileByString(traceInput, forceOutputName)


def CreateArgInputTraceFileByString(traceInput, forceOutputName):
    global arg, okForRun

    if (TestFileExist(traceInput)):
        GetFileInputName(traceInput, forceOutputName)

        arg = '-i ' + traceInput + ' ' + opt
    else:
        LogMsgWarning(traceInput + ' not found.')
        okForRun = False


def CreateArgInputTraceFileByList(traceInput, forceOutputName):
    global arg, okForRun

    if (len(traceInput) > 0):
        if (TestListFileExist(traceInput)):
            GetFileInputName(traceInput[0], forceOutputName)

            traceStr = CreateArgInputTraceFileStructure(traceInput, 'Input', 'Txt')

            newFileName = atOutputDir + '/' + atOutputName + '.json'

            f = open(newFileName, 'w')
            f.write('{\n' + traceStr + '\n}')
            f.close()

            arg = '-i ' + newFileName + ' ' + opt
        else:
            LogMsgWarning('Bad input in traces files list.')
            okForRun = False
    else:
        LogMsgWarning('No Message trace file found in List argument.')
        okForRun = False


def CreateArgInputTraceFileByDico(traceInput, forceOutputName):
    global arg, okForRun

    liMsg = []
    liCpt = []
    for key, value in traceInput.items():
        if (key[0] == 'M'):
            liMsg.append(value)
        if (key[0] == 'C'):
            liCpt.append(value)

    traceStrMsg = ''
    traceStrCpt = ''
    if ((len(liMsg) == 0) and (len(liCpt) == 0)):
        LogMsgWarning('No Message or Counter trace file found in Dictionary argument.')
        okForRun = False
    else:
        if (len(liMsg) > 0):
            GetFileInputName(liMsg[0], forceOutputName)
        else:
            GetFileInputName(liCpt[0], forceOutputName)

        if (len(liMsg) > 0):
            if (TestListFileExist(liMsg)):
                traceStrMsg = '\n' + CreateArgInputTraceFileStructure(liMsg, 'Msg', 'Txt') + '\n'
            else:
                LogMsgWarning('Bad input in Message traces files list.')
                okForRun = False
        if (len(liCpt) > 0):
            if (TestListFileExist(liCpt)):
                traceStrCpt = '\n' + CreateArgInputTraceFileStructure(liCpt, 'Cpt', 'Csv') + '\n'
            else:
                LogMsgWarning('Bad input in Counter files list.')
                okForRun = False

        newFileName = atOutputDir + '/' + atOutputName + '.json'
        f = open(newFileName, 'w')
        if ((len(liMsg) > 0) and (len(liCpt) > 0)):
            f.write('{' + traceStrCpt + ',' + traceStrMsg + '}')
        else:
            f.write('{' + traceStrCpt + traceStrMsg + '}')
        f.close()

        arg = '-i ' + newFileName + ' ' + opt


def GetFileInputName(inputPath, forceOutputName):
    global atOutputName, atOutputDir

    atOutputDir = os.path.dirname(os.path.abspath(inputPath))

    if (len(forceOutputName) == 0):
        atOutputNameTmp = os.path.basename(inputPath)
        atOutputName = os.path.splitext(atOutputNameTmp)[0]
    else:
        atOutputName = forceOutputName

        # LogMsg('GetFileInputName, __file__: ' + __file__)
        # LogMsg('GetFileInputName, __file__ path: ' + os.path.dirname(os.path.abspath(__file__)))
        # LogMsg('GetFileInputName, inputPath: ' + inputPath)
        # LogMsg('GetFileInputName, forceOutputName: ' + forceOutputName)
        # LogMsg('GetFileInputName, atOutputName: ' + atOutputName)
        # LogMsg('GetFileInputName, atOutputDir: ' + atOutputDir)


def CreateArgInputTraceFileStructure(liFile, traceType, fileType):
    output = ' \"trace' + traceType + '\":\n'
    output += '  [\n'
    output += '   {\n'
    output += '    \"ADataType\": \"' + traceType + '\",\n'
    output += '    \"AFileFormat\": \"' + fileType + '\",\n'
    output += '    \"Id\": -1,\n'
    output += '    \"isMonoTreat\": true,\n'
    output += '    \"logType\": \"-\",\n'
    output += '    \"name\": \"-\",\n'
    output += '    \"srcList\": ' + StringTrueOrFalse(len(liFile) > 1) + ',\n'
    output += '    \"files\":\n'
    output += '     [\n'
    output += '      ' + JointStringList(liFile, ',') + '\n'
    output += '     ]\n'
    output += '   }\n'
    output += '  ]'

    return output


def StringTrueOrFalse(v):
    if (v):
        return 'true'
    else:
        return 'false'


@keyword('eCLAT-AnalysisTraces get last global variables')
def eAT_GetLastGlobalVariables():
    return GetLastGlobalVariables()


@keyword('AnalysisTraces get last global variables')
def GetLastGlobalVariables():
    outGlobalVar = {}

    # os.system('ls -t ' + atOutputDir + '/*_Variables*.csv | head -1 > ' + atOutputDir + '/tmp.txt')
    # varFileName = open(atOutputDir + '/tmp.txt', 'r').read().replace('\n', '')
    varFileName = GetGlobalVariablesFileName()

    if (len(varFileName) == 0):
        LogMsgWarning('No Global variables file.')
    else:
        varLine = open(varFileName, 'r').read().split('\n')
        for line in varLine:
            var = line.split(';')
            if (len(var) > 4):
                outGlobalVar.update({var[2]: var[4]})
                if (len(var[3]) > 0):
                    outGlobalVar.update({var[2] + '_Unit': var[3]})

    return outGlobalVar


def TestListFileExist(listPathFile):
    global okForRun

    output = True

    if (len(listPathFile) == 0):
        LogMsgWarning('No Message trace file found in List argument.')
        okForRun = False
    else:
        for fileName in listPathFile:
            TestFileExist(fileName)

    return output


def TestFileExist(pathFile):
    global okForRun

    output = os.path.exists(pathFile)

    if (not (output)):
        LogMsgWarning('File not found: ' + pathFile)
        okForRun = False

    return output


def TestDirExist(pathDir):
    output = os.path.isdir(pathDir)

    if (not (output)):
        LogMsgWarning('Directory not found: ' + pathDir)

    return output


def GetPath(outputFile):
    output = os.path.dirname(os.path.abspath(outputFile))

    return output


# Return value of specific global variables
#  only if last AnalysisTraces run with -g option (by default)
@keyword('eCLAT-AnalysisTraces get global value')
def eAT_GetGlobalValue(varName):
    return GetGlobalValue(varName)


@keyword('AnalysisTraces get global value')
def GetGlobalValue(varName):
    dirVar = GetLastGlobalVariables()
    output = dirVar.get(varName)

    return output


# Copy global variables file in directory
@keyword('eCLAT-AnalysisTraces copy global variables file in ')
def eAT_CopyGlobalVariablesFileIn(outputCopyDir):
    CopyGlobalVariablesFileIn()


@keyword('AnalysisTraces copy global variables file in ')
def CopyGlobalVariablesFileIn(outputCopyDir):
    varFileName = GetGlobalVariablesFileName()

    if (len(varFileName) == 0):
        LogMsgWarning('No Global variables file.')
    else:
        shutil.copy2(varFileName, outputCopyDir)


def GetGlobalVariablesFileName():
    if (len(atOutputDir) == 0):
        output = ''
        LogMsgWarning('No output directory')
    else:
        os.system('ls -t ' + atOutputDir + '/*_Variables*.csv | head -1 > ' + atOutputDir + '/tmp.txt')
        output = open(atOutputDir + '/tmp.txt', 'r').read().replace('\n', '')

    return output


def JointStringList(stringList, sep):
    outputString = ''
    for s in stringList:
        outputString += '\"' + s + '\"' + sep
    output = stringLeft(outputString, len(outputString) - len(sep))

    return output


def stringLeft(s, amount):
    return s[:amount]


def stringRight(s, amount):
    return s[-amount:]


def stringMid(s, offset, amount):
    return s[offset:offset + amount]

